# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.81.0/ankra-cli-darwin-arm64"
      sha256 "c20dff075d5e4b0e9663b2b945bdd9fe504bfff6f6fb1f821c6742e989f8a16e"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.81.0/ankra-cli-darwin-amd64"
      sha256 "877499844bb6511b06bce6cbcb5670419abc583ea0eaaf1f8867f32c232e7786"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.81.0/ankra-cli-linux-arm64"
      sha256 "8050db99f7a6b97d95fbbbec2645390474f8a43f48f053a8be6704452e9cb528"
    end
    on_intel do
